mapper.select:
SELECT m.id, m.created_at, t.id AS tenant_id, t.slug, t.display_name, m.phone, m.text, m.error
FROM sms_messages m
JOIN tenants t ON t.id = m.tenant_id
WHERE m.status = 'FAILED' AND m.created_at >= #{from} AND m.created_at < #{to}
ORDER BY m.created_at DESC, m.id DESC
LIMIT #{limit} OFFSET #{offset}
